						Reason:  "unsupported path rule",
					}},
				},
				Cleanup: agentwrap.CleanupMetadata{Attempted: true, Completed: true},
				Validation: agentwrap.ValidationMetadata{
					Configured: true,
					Final: agentwrap.ValidationResult{
