func smokeAuthorModel(req pruntime.Request) string {
	if req.Provider != "" && req.Model != "" {
		return req.Provider + "/" + req.Model
	}
	if req.Model != "" {
		return req.Model
	}
	return "runtime default"
}

func smokeHarnessSnapshot(prepared smokePrepared) (map[string]string, error) {
	out := map[string]string{}
	err := filepath.WalkDir(prepared.HarnessRoot, func(path string, entry fs.DirEntry, walkErr error) error {
		if walkErr != nil {
			return walkErr
		}
		rel, err := filepath.Rel(prepared.HarnessRoot, path)
		if err != nil {
			return err
		}
		rel = filepath.ToSlash(rel)
		if entry.IsDir() {
			if rel == ".git" || rel == "node_modules" || inside(prepared.RunsRoot, path) || inside(prepared.IssuesRoot, path) {
				return filepath.SkipDir
			}
			return nil
		}
		if len(out) >= maxSmokeAuthoringFiles {
			return fmt.Errorf("harness exceeds %d authoring files", maxSmokeAuthoringFiles)
		}
		if entry.Type()&os.ModeSymlink != 0 {
			return fmt.Errorf("authoring snapshot rejects symlink: %s", rel)
		}
		info, err := entry.Info()
		if err != nil {
			return err
		}
		if !info.Mode().IsRegular() {
			return nil
		}
		if info.Size() > 64<<20 {
			return fmt.Errorf("authoring file exceeds bounded read: %s", rel)
		}
		digest, err := hashFile(path)
		if err != nil {
			return err
		}
		out[rel] = digest
		return nil
	})
	return out, err
}

func changedSmokeHarnessPaths(before, after map[string]string) []string {
	seen := map[string]bool{}
	var changed []string
	for path, digest := range before {
		seen[path] = true
		if after[path] != digest {
			changed = append(changed, path)
		}
	}
	for path := range after {
		if !seen[path] {
			changed = append(changed, path)
		}
	}
	sort.Strings(changed)
	return changed
}

func smokeAuthorPathAllowed(path string, allowed []string) bool {
	path = filepath.ToSlash(filepath.Clean(path))
	for _, candidate := range allowed {
		candidate = filepath.ToSlash(filepath.Clean(candidate))
		if path == candidate || strings.HasPrefix(path, candidate+"/") {
			return true
		}
	}
	return false
}

		return parts[0]
	}
	return strings.Join(parts, ":")
}

func (s Service) startPlanningStageRun(ctx context.Context, sp Sprint, stage PlanningStage, req pruntime.Request) (pruntime.Result, error) {
	key := stageSessionKey(stage, req)
	originalPrompt := req.Prompt
	continuing := false
	state, loadErr := loadStageSessions(sp)
	if loadErr == nil {
		if record, ok := state.Sessions[key]; ok && stageSessionCompatible(record, req) {
			req.SessionID = record.SessionID
			req.SessionAction = "continue"
			req.Prompt = insertStageContinuation(req.Prompt, "Continue the interrupted UltraPlan stage from the existing session. Re-read the current stage prompt and filesystem state, then finish only the requested stage.")
			continuing = true
		}
	}
	previousOnEvent := req.OnEvent
	var mu sync.Mutex
	lastSession := req.SessionID
	persist := func(sessionID string) {
		if strings.TrimSpace(sessionID) == "" {
			return
		}
		mu.Lock()
		defer mu.Unlock()
		if sessionID == lastSession {
			return
		}
		lastSession = sessionID
		current, err := loadStageSessions(sp)
		if err != nil {
			return
		}
		current.Sessions[key] = stageSessionRecord{SessionID: sessionID, Provider: req.Provider, Model: req.Model, WorkDir: req.WorkDir, PromptChecksum: req.PromptRef.Checksum, UpdatedAt: s.now().UTC()}
		_ = saveStageSessions(sp, current)
	}
	req.OnEvent = func(event pruntime.Event) {
		if previousOnEvent != nil {
			previousOnEvent(event)
		}
		persist(event.SessionID)
	}
	result, err := s.startSprintRuntime(ctx, sp, stage, req)
	persist(result.SessionID)
	if continuing && planningSessionNotFound(result, err) && ctx.Err() == nil {
