type controlledEventRun struct {
	id      agentwrap.RunID
	events  chan agentwrap.Event
	result  agentwrap.RunResult
	err     error
	cancels int
}

func (r *controlledEventRun) ID() agentwrap.RunID            { return r.id }
func (r *controlledEventRun) Events() <-chan agentwrap.Event { return r.events }
func (r *controlledEventRun) Wait(ctx context.Context) (agentwrap.RunResult, error) {
	return r.result, r.err
}
func (r *controlledEventRun) Cancel(context.Context) error { r.cancels++; return nil }

type singleRuntime struct{ run agentwrap.Run }

func (f singleRuntime) StartRun(context.Context, agentwrap.RunRequest) (agentwrap.Run, error) {
	return f.run, nil
}
func (f singleRuntime) Capabilities(context.Context) (agentwrap.Capabilities, error) {
	return agentwrap.Capabilities{}, nil
}

// Probe 1: Wait returns instantly; events are held back past the 1s drain
// window. Expect: result loses ALL events/stats with no warning, and OnEvent
// fires after StartRun has already returned.
func TestProbeDrainWindowSilentlyDropsAllEvents(t *testing.T) {
	ch := make(chan agentwrap.Event, 1)
	run := &controlledEventRun{
		id:     "run-lag",
		events: ch,
		result: agentwrap.RunResult{RunID: "run-lag", Status: agentwrap.StatusCompleted, SessionID: "ses_main"},
	}
	var afterReturn int32
	done := make(chan struct{})
	adapter := NewAdapter(singleRuntime{run: run})
	req := Request{Prompt: "p", OnEvent: func(Event) { afterReturn++ }}
	go func() {
		defer close(done)
		time.Sleep(1500 * time.Millisecond)
		ch <- agentwrap.Event{
			ID: "e1", RunID: "run-lag", SessionID: "ses_late", Type: "native.message",
			Payload: agentwrap.EventPayloadWithKind(agentwrap.EventMessage, agentwrap.EventPayload{"text": "late"}),
		}
		close(ch)
	}()
	result, err := adapter.StartRun(context.Background(), req)
	if err != nil {
		t.Fatal(err)
	}
	t.Logf("events=%d stats=%+v warnings=%v sessionIDs=%v",
		len(result.Events), result.EventStats, result.Warnings, result.SessionIDs)
	close(ch)
	select {
	case <-done:
	case <-time.After(3 * time.Second):
	}
	time.Sleep(100 * time.Millisecond)
	t.Logf("OnEvent calls observed after StartRun returned: totalSeen=%d (sent=%d)", afterReturn, 1)
}

// Probe 2: cancelled context + waiter that returns after the 5s grace window.
// Expect synthesized eventless result while events keep flowing afterwards.
func TestProbeGraceBranchAbandonsEvents(t *testing.T) {
	ch := make(chan agentwrap.Event, 4)
	run := &controlledEventRun{
		id:     "run-grace",
		events: ch,
