// window. Expect: result loses ALL events/stats with no warning, and OnEvent
// fires after StartRun has already returned.
func TestProbeDrainWindowSilentlyDropsAllEvents(t *testing.T) {
	ch := make(chan agentwrap.Event, 1)
	run := &controlledEventRun{
		id:     "run-lag",
		events: ch,
		result: agentwrap.RunResult{RunID: "run-lag", Status: agentwrap.StatusCompleted, SessionID: "ses_main"},
	}
	var lateOnEvent int32
	var mu sync.Mutex
	var returnedAt time.Time
	adapter := NewAdapter(singleRuntime{run: run})
	req := Request{Prompt: "p", OnEvent: func(Event) {
		mu.Lock()
		defer mu.Unlock()
		if !returnedAt.IsZero() {
			lateOnEvent++
		}
	}}
	go func() {
		time.Sleep(1500 * time.Millisecond)
		ch <- agentwrap.Event{
			ID: "e1", RunID: "run-lag", SessionID: "ses_late", Type: "native.message",
			Payload: agentwrap.EventPayloadWithKind(agentwrap.EventMessage, agentwrap.EventPayload{"text": "late"}),
		}
		close(ch)
	}()
	result, err := adapter.StartRun(context.Background(), req)
	mu.Lock()
	returnedAt = time.Now()
	mu.Unlock()
	if err != nil {
		t.Fatal(err)
	}
	t.Logf("events=%d stats=%+v warnings=%v sessionIDs=%v",
		len(result.Events), result.EventStats, result.Warnings, result.SessionIDs)
	deadline := time.Now().Add(3 * time.Second)
	for time.Now().Before(deadline) {
		mu.Lock()
		late := lateOnEvent
		mu.Unlock()
		if late > 0 {
			break
		}
		time.Sleep(50 * time.Millisecond)
	}
	mu.Lock()
	t.Logf("post-return OnEvent deliveries: %d (event was emitted into the live stream)", lateOnEvent)
	mu.Unlock()
}

